// Generated by Cypress Author — 2026-10-01
describe('Documentation', () => {
    beforeEach(() => {
        cy.login()
    })

    it('Footer link → opens functional documentation and follows an internal link', () => {
        cy.visit('/')
        cy.get('footer').contains('a', 'Documentation').click()

        cy.url().should('include', '/documentation/specs/INDEX.md')
        cy.get('.documentation-content h1').should('contain', 'Spécifications fonctionnelles')
        cy.get('.documentation-sidebar a[aria-current="page"]').should('contain', 'Spécifications fonctionnelles')

        cy.get('.documentation-content').contains('a', 'MOD-01 — Établissements').click()

        cy.url().should('include', '/documentation/specs/MOD-01-ETABLISSEMENTS.md')
        cy.get('.documentation-content h1').should('contain', 'Établissements')
    })

    it('Tech subfolder document → renders with the active navigation item and isolated HTML access', () => {
        cy.visit('/documentation/tech/dossier/edition-dossiers.md')

        cy.get('.documentation-content h1').should('exist')
        cy.get('.documentation-sidebar a[aria-current="page"]')
            .should('have.attr', 'href')
            .and('include', '/documentation/tech/dossier/edition-dossiers.md')

        cy.request('/documentation/tech/toast-demo.html').then((response) => {
            expect(response.status).to.equal(200)
            expect(response.headers['content-type']).to.include('text/html')
            expect(response.headers['content-security-policy']).to.include('sandbox')
            expect(response.body).to.include('<!DOCTYPE html>')
            expect(response.body).to.include('Démo - Notifications Toast')
        })
    })
})
